package com.texto.emailplatform.segment.web;
import com.texto.emailplatform.common.api.ApiResponse; import com.texto.emailplatform.segment.SegmentService; import com.texto.emailplatform.segment.api.*; import jakarta.validation.Valid; import java.util.*; import org.springframework.web.bind.annotation.*;
@org.springframework.security.access.prepost.PreAuthorize("@campaignAuthorizationService.canRead()")
@RestController @RequestMapping("/api/v1/segments") public class SegmentController {private final SegmentService service;public SegmentController(SegmentService service){this.service=service;}@GetMapping public ApiResponse<List<SegmentResponse>> list(){return ApiResponse.ok(service.list());}@org.springframework.security.access.prepost.PreAuthorize("@campaignAuthorizationService.canManage()") @PostMapping public ApiResponse<SegmentResponse> create(@Valid @RequestBody SegmentRequest r){return ApiResponse.ok(service.create(r));}@org.springframework.security.access.prepost.PreAuthorize("@campaignAuthorizationService.canManage()") @PatchMapping("/{id}") public ApiResponse<SegmentResponse> update(@PathVariable UUID id,@Valid @RequestBody SegmentRequest r){return ApiResponse.ok(service.update(id,r));}@org.springframework.security.access.prepost.PreAuthorize("@campaignAuthorizationService.canManage()") @DeleteMapping("/{id}") public ApiResponse<Void> delete(@PathVariable UUID id){service.delete(id);return ApiResponse.ok(null);}}
